import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseCsv, csvToMarkdownTable } from './convert.mjs';

test('parses a simple csv into rows', () => {
  const rows = parseCsv('name,age\nAda,30\nGrace,85\n');
  assert.deepEqual(rows, [
    ['name', 'age'],
    ['Ada', '30'],
    ['Grace', '85'],
  ]);
});

test('parses quoted fields with embedded commas and escaped quotes', () => {
  const rows = parseCsv('name,quote\n"Lovelace, Ada","She said ""hi"""\n');
  assert.deepEqual(rows, [
    ['name', 'quote'],
    ['Lovelace, Ada', 'She said "hi"'],
  ]);
});

test('converts a simple csv to a github-flavored markdown table', () => {
  const table = csvToMarkdownTable('name,age\nAda,30\nGrace,85\n');
  assert.equal(
    table,
    ['| name | age |', '| --- | --- |', '| Ada | 30 |', '| Grace | 85 |'].join('\n'),
  );
});

test('escapes pipe characters in cells', () => {
  const table = csvToMarkdownTable('a,b\n1|2,3\n');
  assert.equal(table, ['| a | b |', '| --- | --- |', '| 1\\|2 | 3 |'].join('\n'));
});

test('collapses newlines inside quoted cells', () => {
  const table = csvToMarkdownTable('a,b\n"line1\nline2",x\n');
  assert.equal(table, ['| a | b |', '| --- | --- |', '| line1 line2 | x |'].join('\n'));
});

test('throws when a row has a different column count than the header', () => {
  assert.throws(() => csvToMarkdownTable('a,b\n1,2,3\n'), /column/);
});

test('throws on an empty csv', () => {
  assert.throws(() => csvToMarkdownTable(''), /no rows/);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseCSV, toMarkdownTable, csvToMarkdownTable } from './convert.mjs';

test('parseCSV splits simple rows', () => {
  assert.deepEqual(parseCSV('a,b\n1,2\n'), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('parseCSV handles quoted fields with commas and escaped quotes', () => {
  const input = 'name,quote\n"Doe, John","She said ""hi"""\n';
  assert.deepEqual(parseCSV(input), [
    ['name', 'quote'],
    ['Doe, John', 'She said "hi"'],
  ]);
});

test('parseCSV handles newlines embedded in quoted fields', () => {
  const input = 'a,b\n"line1\nline2",2\n';
  assert.deepEqual(parseCSV(input), [
    ['a', 'b'],
    ['line1\nline2', '2'],
  ]);
});

test('parseCSV ignores a trailing blank line', () => {
  assert.deepEqual(parseCSV('a,b\n1,2\n'), [
    ['a', 'b'],
    ['1', '2'],
  ]);
});

test('parseCSV returns an empty array for empty input', () => {
  assert.deepEqual(parseCSV(''), []);
});

test('toMarkdownTable renders header, separator, and body rows', () => {
  const table = toMarkdownTable([
    ['Name', 'Age'],
    ['Ada', '36'],
    ['Grace', '85'],
  ]);
  assert.equal(
    table,
    ['| Name | Age |', '| --- | --- |', '| Ada | 36 |', '| Grace | 85 |'].join('\n'),
  );
});

test('toMarkdownTable escapes pipe characters in cells', () => {
  const table = toMarkdownTable([['A|B'], ['1|2']]);
  assert.equal(table, ['| A\\|B |', '| --- |', '| 1\\|2 |'].join('\n'));
});

test('toMarkdownTable turns embedded newlines into <br>', () => {
  const table = toMarkdownTable([['Cell'], ['line1\nline2']]);
  assert.equal(table, ['| Cell |', '| --- |', '| line1<br>line2 |'].join('\n'));
});

test('toMarkdownTable pads ragged rows to the header width', () => {
  const table = toMarkdownTable([
    ['A', 'B', 'C'],
    ['1'],
  ]);
  assert.equal(table, ['| A | B | C |', '| --- | --- | --- |', '| 1 |  |  |'].join('\n'));
});

test('toMarkdownTable returns an empty string for no rows', () => {
  assert.equal(toMarkdownTable([]), '');
});

test('csvToMarkdownTable converts CSV text end to end', () => {
  const csv = 'Name,Role\nAda,Engineer\nGrace,Admiral\n';
  const table = csvToMarkdownTable(csv);
  assert.equal(
    table,
    ['| Name | Role |', '| --- | --- |', '| Ada | Engineer |', '| Grace | Admiral |'].join('\n'),
  );
});
